package com.yuegang.zhihui.ai.api;import com.yuegang.zhihui.ai.application.*;import com.yuegang.zhihui.ai.security.*;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import jakarta.servlet.http.*;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/ai")public final class AiEvaluationController{private final AiEvaluationService service;private final AiUserResolver users;public AiEvaluationController(AiEvaluationService s,AiUserResolver u){service=s;users=u;}@GetMapping("/summary")ApiResponse<AiAdminSummaryView>summary(HttpServletRequest r){users.require(r,"ai:audit:read");return ApiResponse.success(service.summary(),TraceIdResolver.resolve(r));}@PostMapping("/evaluations/run")ApiResponse<List<EvaluationRunView>>run(HttpServletRequest r){return ApiResponse.success(service.run(users.require(r,"ai:evaluation:execute")),TraceIdResolver.resolve(r));}}
